Here is the commit message:
usb: Fix regression caused by invalid ep0 maxpacket in
 virtual SuperSpeed device

A virtual SuperSpeed device in the FreeBSD BVCP package
(https://bhyve.npulse.net/) presents an invalid ep0 maxpacket size of 256.
It stopped working with Linux following a recent commit because now we
check these sizes more carefully than before.

Fix this regression by using the bMaxpacketSize0 value in the device
descriptor for SuperSpeed or faster devices, even if it is invalid.  This
is a very simple-minded change; we might want to check more carefully for
values that actually make some sense (for instance, no smaller than 64).

Signed-off-by: Alan Stern <stern@rowland.harvard.edu>
Reported-and-tested-by: Roger Whittaker <roger.whittaker@suse.com>
Closes: https://bugzilla.suse.com/show_bug.cgi?id=1220569
Link: https://lore.kernel.org/linux-usb/9efbd569-7059-4575-983f-0ea30df41871@suse.com/
Fixes: 59cf44575456 ("USB: core: Fix oversight in SuperSpeed initialization")
Cc: stable@vger.kernel.org
Link: https://lore.kernel.org/r/4058ac05-237c-4db4-9ecc-5af42bdb4501@rowland.harvard.edu
Signed-off-by: Greg Kroah-Hartman <gregkh@linuxfoundation.org>

Here is the root cause:
The bug was caused by a recent commit that introduced stricter validation checks for the `ep0` maxpacket size in USB devices, which led to the failure of virtual SuperSpeed devices that reported an invalid `bMaxpacketSize0` value of 256. The new checks did not accommodate the possibility of invalid values for SuperSpeed devices, resulting in a regression in functionality.

Here is the patch:
  */
 static int
 hub_port_init(struct usb_hub *hub, struct usb_device *udev, int port1,
 		int retry_counter, struct usb_device_descriptor *dev_descr)
 {
 	struct usb_device	*hdev = hub->hdev;
 	struct usb_hcd		*hcd = bus_to_hcd(hdev->bus);
 	struct usb_port		*port_dev = hub->ports[port1 - 1];
 	int			retries, operations, retval, i;
 	unsigned		delay = HUB_SHORT_RESET_TIME;
 	enum usb_device_speed	oldspeed = udev->speed;
 	const char		*speed;
 	int			devnum = udev->devnum;
 	const char		*driver_name;
 	bool			do_new_scheme;
 	const bool		initial = !dev_descr;
 	int			maxp0;
 	struct usb_device_descriptor	*buf, *descr;

 	buf = kmalloc(GET_DESCRIPTOR_BUFSIZE, GFP_NOIO);
 	if (!buf)
 		return -ENOMEM;

 	/* root hub ports have a slightly longer reset period
 	 * (from USB 2.0 spec, section 7.1.7.5)
 	 */
 	if (!hdev->parent) {
 		delay = HUB_ROOT_RESET_TIME;
 		if (port1 == hdev->bus->otg_port)
 			hdev->bus->b_hnp_enable = 0;
 	}

 	/* Some low speed devices have problems with the quick delay, so */
 	/*  be a bit pessimistic with those devices. RHbug #23670 */
 	if (oldspeed == USB_SPEED_LOW)
 		delay = HUB_LONG_RESET_TIME;

 	/* Reset the device; full speed may morph to high speed */
 	/* FIXME a USB 2.0 device may morph into SuperSpeed on reset. */
 	retval = hub_port_reset(hub, port1, udev, delay, false);
 	if (retval < 0)		/* error or disconnect */
 		goto fail;
 	/* success, speed is known */

 	retval = -ENODEV;

 	/* Don't allow speed changes at reset, except usb 3.0 to faster */
 	if (oldspeed != USB_SPEED_UNKNOWN && oldspeed != udev->speed &&
 	    !(oldspeed == USB_SPEED_SUPER && udev->speed > oldspeed)) {
 		dev_dbg(&udev->dev, "device reset changed speed!\n");
 		goto fail;
 	}
 	oldspeed = udev->speed;

 	if (initial) {
 		/* USB 2.0 section 5.5.3 talks about ep0 maxpacket ...
 		 * it's fixed size except for full speed devices.
 		 */
 		switch (udev->speed) {
 		case USB_SPEED_SUPER_PLUS:
 		case USB_SPEED_SUPER:
 			udev->ep0.desc.wMaxPacketSize = cpu_to_le16(512);
 			break;
 		case USB_SPEED_HIGH:		/* fixed at 64 */
 			udev->ep0.desc.wMaxPacketSize = cpu_to_le16(64);
 			break;
 		case USB_SPEED_FULL:		/* 8, 16, 32, or 64 */
 			/* to determine the ep0 maxpacket size, try to read
 			 * the device descriptor to get bMaxPacketSize0 and
 			 * then correct our initial guess.
 			 */
 			udev->ep0.desc.wMaxPacketSize = cpu_to_le16(64);
 			break;
 		case USB_SPEED_LOW:		/* fixed at 8 */
 			udev->ep0.desc.wMaxPacketSize = cpu_to_le16(8);
 			break;
 		default:
 			goto fail;
 		}
 	}

 	speed = usb_speed_string(udev->speed);

 	/*
 	 * The controller driver may be NULL if the controller device
 	 * is the middle device between platform device and roothub.
 	 * This middle device may not need a device driver due to
 	 * all hardware control can be at platform device driver, this
 	 * platform device is usually a dual-role USB controller device.
 	 */
 	if (udev->bus->controller->driver)
 		driver_name = udev->bus->controller->driver->name;
 	else
 		driver_name = udev->bus->sysdev->driver->name;

 	if (udev->speed < USB_SPEED_SUPER)
 		dev_info(&udev->dev,
 				"%s %s USB device number %d using %s\n",
 				(initial ? "new" : "reset"), speed,
 				devnum, driver_name);

 	if (initial) {
 		/* Set up TT records, if needed  */
 		if (hdev->tt) {
 			udev->tt = hdev->tt;
 			udev->ttport = hdev->ttport;
 		} else if (udev->speed != USB_SPEED_HIGH
 				&& hdev->speed == USB_SPEED_HIGH) {
 			if (!hub->tt.hub) {
 				dev_err(&udev->dev, "parent hub has no TT\n");
 				retval = -EINVAL;
 				goto fail;
 			}
 			udev->tt = &hub->tt;
 			udev->ttport = port1;
 		}
 	}

 	/* Why interleave GET_DESCRIPTOR and SET_ADDRESS this way?
 	 * Because device hardware and firmware is sometimes buggy in
 	 * this area, and this is how Linux has done it for ages.
 	 * Change it cautiously.
 	 *
 	 * NOTE:  If use_new_scheme() is true we will start by issuing
 	 * a 64-byte GET_DESCRIPTOR request.  This is what Windows does,
 	 * so it may help with some non-standards-compliant devices.
 	 * Otherwise we start with SET_ADDRESS and then try to read the
 	 * first 8 bytes of the device descriptor to get the ep0 maxpacket
 	 * value.
 	 */
 	do_new_scheme = use_new_scheme(udev, retry_counter, port_dev);

 	for (retries = 0; retries < GET_DESCRIPTOR_TRIES; (++retries, msleep(100))) {
 		if (hub_port_stop_enumerate(hub, port1, retries)) {
 			retval = -ENODEV;
 			break;
 		}

 		if (do_new_scheme) {
 			retval = hub_enable_device(udev);
 			if (retval < 0) {
 				dev_err(&udev->dev,
 					"hub failed to enable device, error %d\n",
 					retval);
 				goto fail;
 			}

 			maxp0 = get_bMaxPacketSize0(udev, buf,
 					GET_DESCRIPTOR_BUFSIZE, retries == 0);
 			if (maxp0 > 0 && !initial &&
 					maxp0 != udev->descriptor.bMaxPacketSize0) {
 				dev_err(&udev->dev, "device reset changed ep0 maxpacket size!\n");
 				retval = -ENODEV;
 				goto fail;
 			}

 			retval = hub_port_reset(hub, port1, udev, delay, false);
 			if (retval < 0)		/* error or disconnect */
 				goto fail;
 			if (oldspeed != udev->speed) {
 				dev_dbg(&udev->dev,
 					"device reset changed speed!\n");
 				retval = -ENODEV;
 				goto fail;
 			}
 			if (maxp0 < 0) {
 				if (maxp0 != -ENODEV)
 					dev_err(&udev->dev, "device descriptor read/64, error %d\n",
 							maxp0);
 				retval = maxp0;
 				continue;
 			}
 		}

 		for (operations = 0; operations < SET_ADDRESS_TRIES; ++operations) {
 			retval = hub_set_address(udev, devnum);
 			if (retval >= 0)
 				break;
 			msleep(200);
 		}
 		if (retval < 0) {
 			if (retval != -ENODEV)
 				dev_err(&udev->dev, "device not accepting address %d, error %d\n",
 						devnum, retval);
 			goto fail;
 		}
 		if (udev->speed >= USB_SPEED_SUPER) {
 			devnum = udev->devnum;
 			dev_info(&udev->dev,
 					"%s SuperSpeed%s%s USB device number %d using %s\n",
 					(udev->config) ? "reset" : "new",
 				 (udev->speed == USB_SPEED_SUPER_PLUS) ?
 						" Plus" : "",
 				 (udev->ssp_rate == USB_SSP_GEN_2x2) ?
 						" Gen 2x2" :
 				 (udev->ssp_rate == USB_SSP_GEN_2x1) ?
 						" Gen 2x1" :
 				 (udev->ssp_rate == USB_SSP_GEN_1x2) ?
 						" Gen 1x2" : "",
 				 devnum, driver_name);
 		}

 		/*
 		 * cope with hardware quirkiness:
 		 *  - let SET_ADDRESS settle, some device hardware wants it
 		 *  - read ep0 maxpacket even for high and low speed,
 		 */
 		msleep(10);

 		if (do_new_scheme)
 			break;

 		maxp0 = get_bMaxPacketSize0(udev, buf, 8, retries == 0);
 		if (maxp0 < 0) {
 			retval = maxp0;
 			if (retval != -ENODEV)
 				dev_err(&udev->dev,
 					"device descriptor read/8, error %d\n",
 					retval);
 		} else {
 			u32 delay;

 			if (!initial && maxp0 != udev->descriptor.bMaxPacketSize0) {
 				dev_err(&udev->dev, "device reset changed ep0 maxpacket size!\n");
 				retval = -ENODEV;
 				goto fail;
 			}

 			delay = udev->parent->hub_delay;
 			udev->hub_delay = min_t(u32, delay,
 						USB_TP_TRANSMISSION_DELAY_MAX);
 			retval = usb_set_isoch_delay(udev);
 			if (retval) {
 				dev_dbg(&udev->dev,
 					"Failed set isoch delay, error %d\n",
 					retval);
 				retval = 0;
 			}
 			break;
 		}
 	}
 	if (retval)
 		goto fail;

 	/*
 	 * Check the ep0 maxpacket guess and correct it if necessary.
 	 * maxp0 is the value stored in the device descriptor;
 	 * i is the value it encodes (logarithmic for SuperSpeed or greater).
 	 */
 	i = maxp0;
 	if (udev->speed >= USB_SPEED_SUPER) {
 		if (maxp0 <= 16)
 			i = 1 << maxp0;
 		else
 			i = 0;		/* Invalid */
 	}
 	if (usb_endpoint_maxp(&udev->ep0.desc) == i) {
 		;	/* Initial ep0 maxpacket guess is right */
-	} else if ((udev->speed == USB_SPEED_FULL ||
+	} else if (((udev->speed == USB_SPEED_FULL ||
 				udev->speed == USB_SPEED_HIGH) &&
-			(i == 8 || i == 16 || i == 32 || i == 64)) {
+			(i == 8 || i == 16 || i == 32 || i == 64)) ||
+			(udev->speed >= USB_SPEED_SUPER && i > 0)) {
 		/* Initial guess is wrong; use the descriptor's value */
 		if (udev->speed == USB_SPEED_FULL)
 			dev_dbg(&udev->dev, "ep0 maxpacket = %d\n", i);
 		else
 			dev_warn(&udev->dev, "Using ep0 maxpacket: %d\n", i);
 		udev->ep0.desc.wMaxPacketSize = cpu_to_le16(i);
 		usb_ep0_reinit(udev);
 	} else {
 		/* Initial guess is wrong and descriptor's value is invalid */
 		dev_err(&udev->dev, "Invalid ep0 maxpacket: %d\n", maxp0);
 		retval = -EMSGSIZE;
 		goto fail;
 	}

 	descr = usb_get_device_descriptor(udev);
 	if (IS_ERR(descr)) {
 		retval = PTR_ERR(descr);
 		if (retval != -ENODEV)
 			dev_err(&udev->dev, "device descriptor read/all, error %d\n",
 					retval);
 		goto fail;
 	}
 	if (initial)
 		udev->descriptor = *descr;
 	else
 		*dev_descr = *descr;
 	kfree(descr);

 	/*
 	 * Some superspeed devices have finished the link training process
 	 * and attached to a superspeed hub port, but the device descriptor
 	 * got from those devices show they aren't superspeed devices. Warm
 	 * reset the port attached by the devices can fix them.
 	 */
 	if ((udev->speed >= USB_SPEED_SUPER) &&
 			(le16_to_cpu(udev->descriptor.bcdUSB) < 0x0300)) {
 		dev_err(&udev->dev, "got a wrong device descriptor, warm reset device\n");
 		hub_port_reset(hub, port1, udev, HUB_BH_RESET_TIME, true);
 		retval = -EINVAL;
 		goto fail;
 	}

 	usb_detect_quirks(udev);

 	if (le16_to_cpu(udev->descriptor.bcdUSB) >= 0x0201) {
 		retval = usb_get_bos_descriptor(udev);
 		if (!retval) {
 			udev->lpm_capable = usb_device_supports_lpm(udev);
 			udev->lpm_disable_count = 1;
 			usb_set_lpm_parameters(udev);
 			usb_req_set_sel(udev);
 		}
 	}

 	retval = 0;
 	/* notify HCD that we have a device connected and addressed */
 	if (hcd->driver->update_device)
 		hcd->driver->update_device(hcd, udev);
 	hub_set_initial_usb2_lpm_policy(udev);
 fail:
 	if (retval) {
 		hub_port_disable(hub, port1, 0);
 		update_devnum(udev, devnum);	/* for disconnect processing */
 	}
 	kfree(buf);
 	return retval;
 }



